32	/**
33	 * 并发与幂等边界测试：真实 H2 行锁 + 唯一约束，协调真实并发操作并设置超时。
34	 */
35	@SpringBootTest
36	@Import(TestClockConfig.class)
37	class RideConcurrencyTest {
38	
39	    @Autowired
40	    private RideService service;
41	
42	    @Autowired
43	    private JdbcTemplate jdbc;
44	
45	    private ExecutorService pool;
46	
47	    @BeforeEach
48	    void setUp() {
