50	        jdbc.update("DELETE FROM daily_check_item");
51	        jdbc.update("DELETE FROM daily_check");
52	        jdbc.update("DELETE FROM trial_run");
53	        jdbc.update("DELETE FROM runtime_reading");
54	        jdbc.update("DELETE FROM ride_event");
55	        jdbc.update("DELETE FROM ride");
56	        pool = Executors.newFixedThreadPool(6);
57	    }
58	
59	    @AfterEach
60	    void tearDown() throws InterruptedException {
61	        pool.shutdownNow();
62	        assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS));
63	    }
64	
65	    private long createReadyRide(String keyPrefix) {
66	        long id = ((Number) service.createRide(
67	                new CreateRideRequest("跳楼机", 8, 60)).get("rideId")).longValue();
68	        service.dailyCheck(id, new DailyCheckRequest(keyPrefix + "-check", List.of(
69	                new CheckItem("压杠", true),
70	                new CheckItem("安全带", true),
71	                new CheckItem("联锁装置", true))));
72	        service.trialRun(id, new TrialRunRequest(keyPrefix + "-t1", true));
73	        service.trialRun(id, new TrialRunRequest(keyPrefix + "-t2", true));
74	        service.trialRun(id, new TrialRunRequest(keyPrefix + "-t3", true));
75	        return id;
76	    }
77	
78	    /** 并发执行同一批任务，等待全部完成并收集结果。 */
79	    private <T> List<T> runConcurrently(List<Callable<T>> tasks) throws Exception {
80	        CountDownLatch ready = new CountDownLatch(tasks.size());
81	        CountDownLatch start = new CountDownLatch(1);
82	        List<Callable<T>> wrapped = tasks.stream()
83	                .<Callable<T>>map(task -> () -> {
84	                    ready.countDown();
85	                    assertTrue(start.await(10, TimeUnit.SECONDS));
86	                    return task.call();
87	                })
88	                .toList();
89	        List<Future<T>> futures = wrapped.stream().map(pool::submit).toList();
90	        assertTrue(ready.await(10, TimeUnit.SECONDS));
91	        start.countDown();
92	        return futures.stream().map(future -> {
93	            try {
94	                return future.get(30, TimeUnit.SECONDS);
95	            } catch (Exception e) {
96	                throw new IllegalStateException("并发任务失败", e);
97	            }
98	        }).toList();
99	    }
100	
101	    @Test
102	    @DisplayName("并发开放唯一成功：同一设备同时刻只允许一条状态链")
103	    void concurrentOpenOnlyOneSucceeds() throws Exception {
104	        long rideId = createReadyRide("co");
105	        int threads = 6;
106	        List<Callable<Integer>> tasks = java.util.stream.IntStream.range(0, threads)
107	                .mapToObj(i -> (Callable<Integer>) () -> {
108	                    try {
109	                        return service.open(rideId, new OpenRequest("co-open-" + i)).status();
110	                    } catch (ApiException e) {
111	                        return e.status().value();
112	                    }
113	                })
114	                .toList();
115	
116	        List<Integer> results = runConcurrently(tasks);
117	        assertEquals(1, results.stream().filter(s -> s == 200).count(),
118	                "并发开放必须唯一成功：" + results);
119	        assertEquals(threads - 1, results.stream().filter(s -> s == 409).count());
120	        assertEquals("OPEN", service.getRide(rideId).get("status"));
121	        // 启停链中仅一条 OPEN 事件
122	        long openEvents = service.listEvents(rideId).stream()
123	                .filter(ev -> "OPEN".equals(ev.get("event_type"))).count();
124	        assertEquals(1, openEvents);
125	    }
126	
127	    @Test
128	    @DisplayName("停运开放竞态：终态唯一，不得既停运又显示开放")
129	    void openAndSafetyFaultRaceHasSingleTerminalState() throws Exception {
130	        long rideId = createReadyRide("race");
131	        Callable<String> open = () -> {
132	            try {
133	                service.open(rideId, new OpenRequest("race-open"));
134	                return "OPEN_OK";
135	            } catch (ApiException e) {
136	                return "OPEN_" + e.status().value();
137	            }
138	        };
139	        Callable<String> fault = () -> {
140	            try {
141	                service.safetyFault(rideId, new SafetyFaultRequest("race-fault", "压杠"));
142	                return "FAULT_OK";
143	            } catch (ApiException e) {
144	                return "FAULT_" + e.status().value();
145	            }
146	        };
147	
148	        List<String> results = runConcurrently(List.of(open, fault));
149	        String finalStatus = (String) service.getRide(rideId).get("status");
150	        // 单状态字段保证唯一终态：开放后遇故障必停运，或故障先于开放则开放失败
151	        assertEquals("STOPPED", finalStatus,
152	                "竞态结果必须收敛为停运终态，结果=" + results);
153	        // 安全装置失效上报必须成功（立即停运语义不被竞态吞掉）
154	        assertTrue(results.contains("FAULT_OK"), "故障停运必须生效：" + results);
155	        // 启停链一致：若存在 OPEN 事件，其后必有 FAULT_STOP，且归档前不再开放
156	        List<String> types = service.listEvents(rideId).stream()
157	                .map(ev -> (String) ev.get("event_type")).toList();
158	        int openIndex = types.indexOf("OPEN");
159	        if (openIndex >= 0) {
160	            assertTrue(types.subList(openIndex, types.size()).contains("FAULT_STOP"),
161	                    "开放后停运必须出现在启停链中：" + types);
162	            assertEquals(openIndex, types.lastIndexOf("OPEN"), "不得重复开放：" + types);
163	        }
164	    }
165	
166	    @Test
167	    @DisplayName("并发同键重放：全部返回首次结果，业务只执行一次")
168	    void concurrentSameRequestIdReplaysOnce() throws Exception {
169	        long rideId = createReadyRide("idem");
170	        int threads = 6;
